  return (
    <>
      {(["fil", "en"] as const).map((language) => (
        <Composition key={`bhs-support-environment-${language}`} id={language === "fil" ? "BhsSupportEnvironmentStoryFil" : "BhsSupportEnvironmentStoryEn"}
